66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that contains
73	     * at least one dot. Whitespace and additional {@code @} characters are disallowed.
74	     */
75	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
76	
77	    /**
78	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
79	     * owner's id, customer code, registration date and membership level, so audit side-effects can
80	     * be observed independently of the HTTP response.
81	     */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    /**
85	     * Common street-type abbreviations expanded during address normalization. Keys and values are
86	     * upper-cased, matching the state of the address after whitespace and case normalization.
87	     */
88	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
89	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
90	
91	    /**
92	     * Required national-number length per E.164 country calling code. After normalization the leading
93	     * country code is stripped and the remaining national digits must match the expected count exactly
94	     * (e.g. {@code +61} requires 9 national digits, {@code +1} requires 10). Country codes not listed
95	     * here are only subject to the generic E.164 length bounds.
96	     */
97	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
98	        Map.of("1", 10, "61", 9);
99	
100	    private final ClinicService clinicService;
101	
102	    private final OwnerMapper ownerMapper;
103	
104	    private final PetMapper petMapper;
105	
106	    private final VisitMapper visitMapper;
107	
108	    public OwnerRestControllerV1(ClinicService clinicService,
109	                                 OwnerMapper ownerMapper,
110	                                 PetMapper petMapper,
111	                                 VisitMapper visitMapper) {
112	        this.clinicService = clinicService;
113	        this.ownerMapper = ownerMapper;
114	        this.petMapper = petMapper;
115	        this.visitMapper = visitMapper;
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
121	        Collection<Owner> owners;
122	        if (lastName != null) {
123	            owners = this.clinicService.findOwnerByLastName(lastName);
124	        } else {
125	            owners = this.clinicService.findAllOwners();
126	        }
127	        if (owners.isEmpty()) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
136	        Owner owner = this.clinicService.findOwnerById(ownerId);
137	        if (owner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
146	        validateRequiredOwnerFields(ownerFieldsDto);
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
150	        owner.setTelephone(normalizedTelephone);
151	        owner.setEmail(normalizeEmail(owner.getEmail()));
152	        owner.setAddress(normalizeAddress(owner.getAddress()));
153	        LocalDate effectiveRegistrationDate =
154	            owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
155	        owner.setRegistrationDate(rollToBusinessDay(effectiveRegistrationDate));
156	        rejectDailyLimitReached(owner.getRegistrationDate());
157	        rejectCityAtCapacity(owner.getCity());
158	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
159	            assignHousehold(owner);
160	        }
161	        rejectDuplicateIdentity(owner, normalizedTelephone);
162	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
163	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
164	        owner.setHouseholdSize(countHousehold(owner.getHouseholdId()));
165	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
166	        this.clinicService.saveOwner(owner);
167	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
168	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
169	            ownerMapper.membershipLevel(owner));
170	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
171	        headers.setLocation(UriComponentsBuilder.newInstance()
172	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
173	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
174	    }
