270	    /**
271	     * Builds the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
272	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3}
273	     * is the upper-cased first three letters of the owner's last name, and {@code NNNN} is a per-city
274	     * 4-digit zero-padded sequence equal to one more than the number of owners already in that city.
275	     * For example an owner named "Smithers" in "Springfield" created when 10 owners already live in
276	     * Springfield gets {@code 'SPR-SMI-0011'}.
277	     *
278	     * @param city the owner's city
279	     * @param lastName the owner's last name
280	     * @return the assigned customer code
281	     */
282	    /**
283	     * Counts how many existing owners share the given first and last name, compared
284	     * case-insensitively, at the moment before the new owner is persisted. The result is
285	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
286	     * stood when the owner was created rather than being recomputed on later reads.
287	     *
288	     * @param firstName the first name of the owner being created
289	     * @param lastName the last name of the owner being created
290	     * @return the number of pre-existing owners with the same first and last name
291	     */
292	    private int countNamesakes(String firstName, String lastName) {
293	        String first = firstName == null ? "" : firstName;
294	        String last = lastName == null ? "" : lastName;
295	        return (int) this.clinicService.findAllOwners().stream()
296	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
297	                && last.equalsIgnoreCase(existing.getLastName()))
298	            .count();
299	    }
300	
301	    private String nextCustomerCode(String city, String lastName) {
302	        String cityLetters = city == null ? "" : city;
303	        String city3 = cityLetters.substring(0, Math.min(3, cityLetters.length())).toUpperCase(Locale.ROOT);
304	        String letters = lastName == null ? "" : lastName;
305	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
306	        String normalizedCity = normalizeForComparison(city);
307	        int sequence = (int) this.clinicService.findAllOwners().stream()
308	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
309	            .count() + 1;
310	        return String.format("%s-%s-%04d", city3, last3, sequence);
311	    }
