313	    /**
314	     * Rejects an owner payload that is missing or blank in any of the required fields
315	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
316	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
317	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
318	     * guard enforces the rule uniformly for every required field.
319	     *
320	     * @param ownerFieldsDto the submitted owner payload
321	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
322	     */
323	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
324	        List<String> invalidFields = new ArrayList<>();
325	        if (isBlank(ownerFieldsDto.getFirstName())) {
326	            invalidFields.add("firstName");
327	        }
328	        if (isBlank(ownerFieldsDto.getLastName())) {
329	            invalidFields.add("lastName");
330	        }
331	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
332	            invalidFields.add("address");
333	        }
334	        if (isBlank(ownerFieldsDto.getCity())) {
335	            invalidFields.add("city");
336	        }
337	        if (isBlank(ownerFieldsDto.getTelephone())) {
338	            invalidFields.add("telephone");
339	        }
340	        if (!invalidFields.isEmpty()) {
341	            throw new InvalidOwnerFieldsException(invalidFields);
342	        }
343	    }
344	
345	    private boolean isBlank(String value) {
346	        return value == null || value.isBlank();
347	    }
348	
349	    /**
350	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
351	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
352	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
353	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
354	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
355	     *
356	     * @param telephone the raw telephone value from the submitted owner payload
357	     * @return the normalized E.164 telephone number
358	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
359	     */
360	    private String normalizeTelephone(String telephone) {
361	        String raw = telephone == null ? "" : telephone.strip();
362	        boolean hasCountryCode = raw.startsWith("+");
363	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
364	        String digits;
365	        if (hasCountryCode) {
366	            digits = cleaned.substring(1);
367	        } else {
368	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
369	            digits = "61" + national;
370	        }
371	        if (!digits.matches("[0-9]{8,15}")) {
372	            throw new InvalidOwnerFieldsException(List.of("telephone"));
373	        }
374	        validateNationalNumberLength(digits);
375	        return "+" + digits;
376	    }
377	
378	    /**
379	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
380	     * country calling code) has the exact length required for that country. The country code is matched
381	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
382	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
383	     *
384	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
385	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
386	     */
387	    private void validateNationalNumberLength(String digits) {
388	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
389	            String countryCode = entry.getKey();
390	            if (digits.startsWith(countryCode)) {
391	                int nationalLength = digits.length() - countryCode.length();
392	                if (nationalLength != entry.getValue()) {
393	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
394	                }
395	                return;
396	            }
397	        }
398	    }
399	
400	    /**
401	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
402	     * returning {@code null} when the value cannot form a valid E.164 number.
403	     *
404	     * @param telephone an existing owner's stored telephone value
405	     * @return the E.164 form, or {@code null} if it cannot be normalized
406	     */
407	    private String toE164OrNull(String telephone) {
408	        try {
409	            return normalizeTelephone(telephone);
410	        } catch (InvalidOwnerFieldsException ex) {
411	            return null;
412	        }
413	    }
414	
415	    /**
416	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
417	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
418	     * accepted value is trimmed and lower-cased before it is stored and returned.
419	     *
420	     * @param email the raw email value from the submitted owner payload, may be {@code null}
421	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
422	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address
423	     */
424	    private String normalizeEmail(String email) {
425	        if (email == null) {
426	            return null;
427	        }
428	        String trimmed = email.strip();
429	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
430	            throw new InvalidOwnerFieldsException(List.of("email"));
431	        }
432	        return trimmed.toLowerCase(Locale.ROOT);
433	    }
434	
435	    /**
436	     * Rejects creating an owner whose derived identity key exactly equals that of any existing owner.
437	     * This single check consolidates the former separate telephone, email and household duplicate
438	     * checks: an owner is a duplicate only when its <em>whole</em> identity key
439	     * ({@code '<normalizedTelephone>|<email>|<householdId>'}) matches an existing owner's. Because the
440	     * telephone is part of the key, two members of the same household (same {@code householdId}) with
441	     * different telephones have different identity keys and are both allowed.
442	     *
443	     * <p>The new owner's telephone is already E.164-normalized and its email already lower-cased.
444	     * Existing owners' telephones are converted to E.164 form and their emails lower-cased before the
445	     * key is built, so differently-formatted representations of the same values still collide.
446	     *
447	     * @param owner the owner being created, whose email and household id contribute to the key
448	     * @param normalizedTelephone the E.164 telephone of the owner being created
449	     * @throws DuplicateOwnerIdentityException if another owner already has the same whole identity key
450	     */
451	    private void rejectDuplicateIdentity(Owner owner, String normalizedTelephone) {
452	        String newKey = identityKey(normalizedTelephone, owner.getEmail(), owner.getHouseholdId());
453	        boolean duplicate = this.clinicService.findAllOwners().stream()
454	            .anyMatch(existing -> newKey.equals(identityKey(
455	                toE164OrNull(existing.getTelephone()),
456	                existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT),
457	                existing.getHouseholdId())));
458	        if (duplicate) {
459	            throw new DuplicateOwnerIdentityException(newKey);
460	        }
461	    }
462	
463	    /**
464	     * Builds the duplicate-detection identity key, formatted
465	     * {@code '<normalizedTelephone>|<email>|<householdId>'}. The telephone, email and household-id
466	     * segments are each replaced with the empty string when {@code null}, so an absent email or
467	     * household id contributes an empty segment rather than the literal {@code "null"}.
468	     *
469	     * @param normalizedTelephone the E.164 telephone, may be {@code null}
470	     * @param email the lower-cased email, may be {@code null}
471	     * @param householdId the household id, may be {@code null}
472	     * @return the identity key
473	     */
474	    private String identityKey(String normalizedTelephone, String email, String householdId) {
475	        return (normalizedTelephone == null ? "" : normalizedTelephone)
476	            + "|" + (email == null ? "" : email)
477	            + "|" + (householdId == null ? "" : householdId);
478	    }
479	
480	    /**
481	     * The maximum number of owners a single city may contain. Once a city already holds this many
482	     * owners, creating another owner in that city is rejected.
483	     */
484	    private static final int MAX_OWNERS_PER_CITY = 50;
485	
486	    /**
487	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
488	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
489	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
490	     * counting used elsewhere.
491	     *
492	     * @param city the city of the owner being created
493	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
494	     */
495	    /**
496	     * The maximum number of owners that may be registered on a single day. Once this many owners
497	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
498	     */
499	    private static final int MAX_OWNERS_PER_DAY = 100;
500	
501	    /**
502	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
503	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
504	     * registration date of the owner being created.
505	     *
506	     * @param registrationDate the registration date of the owner being created
507	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
508	     */
509	    /**
510	     * Rolls an effective registration date forward onto a business day. A registration date must fall
511	     * on a weekday: when the supplied or defaulted date is a Saturday or Sunday it is rolled forward to
512	     * the next Monday and that adjusted date becomes the owner's {@code registrationDate}. A weekday date
513	     * is returned unchanged. Every value derived from the registration date (the daily create-limit
514	     * count, the membership number's year segment, and so on) uses this adjusted date.
515	     *
516	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
517	     * @return the same date if it is a weekday, otherwise the following Monday
518	     */
519	    private LocalDate rollToBusinessDay(LocalDate date) {
520	        DayOfWeek day = date.getDayOfWeek();
521	        if (day == DayOfWeek.SATURDAY) {
522	            return date.plusDays(2);
523	        }
524	        if (day == DayOfWeek.SUNDAY) {
525	            return date.plusDays(1);
526	        }
527	        return date;
528	    }
529	
530	    private void rejectDailyLimitReached(LocalDate registrationDate) {
531	        long ownersToday = this.clinicService.findAllOwners().stream()
532	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
533	            .count();
534	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
535	            throw new DailyOwnerLimitExceededException(registrationDate);
536	        }
537	    }
538	
539	    /**
540	     * The number of owners that must already share a {@code registrationDate} before a newly created
541	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
542	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
543	     */
544	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
545	
546	    /**
547	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
548	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
549	     * the same registration date at the time this owner is created. Existing owners are counted by their
550	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
551	     * daily create-limit accumulation.
552	     *
553	     * @param registrationDate the registration date of the owner being created
554	     * @return {@code true} if the day already holds more than the threshold number of owners
555	     */
556	    private boolean isBulkSignupDay(LocalDate registrationDate) {
557	        long ownersToday = this.clinicService.findAllOwners().stream()
558	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
559	            .count();
560	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
561	    }
562	
563	    private void rejectCityAtCapacity(String city) {
564	        String normalizedCity = normalizeForComparison(city);
565	        long ownersInCity = this.clinicService.findAllOwners().stream()
566	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
567	            .count();
568	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
569	            throw new OwnerCityCapacityExceededException(city);
570	        }
571	    }
572	
573	    /**
574	     * Assigns the owner being created a household identifier when the request opts into sharing a
575	     * household. The identifier is a stable value derived from the owner's normalized last name and
576	     * address (see {@link #householdId}), so every owner in the same household is given the exact same
577	     * value regardless of creation order. Any already-existing owner in the same household that has no
578	     * identifier yet is back-filled with the same value so the whole household stays consistent.
579	     *
580	     * @param owner the owner being created, whose household id is set in place
581	     */
582	    private void assignHousehold(Owner owner) {
583	        String householdId = householdId(owner.getLastName(), owner.getAddress());
584	        String normalizedLastName = normalizeForComparison(owner.getLastName());
585	        String normalizedAddress = normalizeAddress(owner.getAddress());
586	        for (Owner existing : this.clinicService.findAllOwners()) {
587	            if (existing.getHouseholdId() == null
588	                && normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
589	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
590	                existing.setHouseholdId(householdId);
591	                this.clinicService.saveOwner(existing);
592	            }
593	        }
594	        owner.setHouseholdId(householdId);
595	    }
596	
597	    /**
598	     * Counts how many owners belong to the household the owner being created has just been assigned to,
599	     * inclusive of that owner. Existing owners are matched by their {@code householdId} equalling the
600	     * given identifier; the owner being created is added on because it is counted before being persisted.
601	     * An owner that did not opt into a shared household (its {@code householdId} is {@code null}) is a
602	     * household of one. The value is snapshotted on the owner.
603	     *
604	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
605	     * @return the number of household members, including the owner being created
606	     */
607	    private int countHousehold(String householdId) {
608	        if (householdId == null) {
609	            return 1;
610	        }
611	        long existing = this.clinicService.findAllOwners().stream()
612	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
613	            .count();
614	        return (int) existing + 1;
615	    }
616	
617	    /**
618	     * Derives the stable household identifier for a given last name and address. The value is
619	     * {@code 'HH-' + <12 upper-case hex chars>} of the SHA-256 digest of the normalized last name and
620	     * address (see {@link #normalizeForComparison}), joined by a delimiter. Two owners that resolve to
621	     * the same household therefore always produce the same identifier.
622	     *
623	     * @param lastName the owner's last name
624	     * @param address the owner's address
625	     * @return the stable household identifier
626	     */
627	    private String householdId(String lastName, String address) {
628	        String key = normalizeForComparison(lastName) + "\n" + normalizeAddress(address);
629	        try {
630	            byte[] digest = MessageDigest.getInstance("SHA-256")
631	                .digest(key.getBytes(StandardCharsets.UTF_8));
632	            StringBuilder hex = new StringBuilder();
633	            for (int i = 0; i < 6; i++) {
634	                hex.append(String.format("%02X", digest[i]));
635	            }
636	            return "HH-" + hex;
637	        } catch (NoSuchAlgorithmException ex) {
638	            throw new IllegalStateException("SHA-256 not available", ex);
639	        }
640	    }
641	
642	    /**
643	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
644	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
645	     * result is lower-cased. A {@code null} value normalizes to the empty string.
646	     *
647	     * @param value the value to normalize, may be {@code null}
648	     * @return the normalized value
649	     */
650	    private String normalizeForComparison(String value) {
651	        if (value == null) {
652	            return "";
653	        }
654	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
655	    }
656	
657	    /**
658	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
659	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
660	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
661	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
662	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
663	     * that is stored, returned, and used for every address comparison (household duplicate detection
664	     * and the shared household id).
665	     *
666	     * @param address the raw address value from the submitted owner payload, may be {@code null}
667	     * @return the normalized address
668	     */
669	    private String normalizeAddress(String address) {
670	        if (address == null) {
671	            return "";
672	        }
673	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
674	        if (collapsed.isEmpty()) {
675	            return "";
676	        }
677	        String[] tokens = collapsed.split(" ");
678	        StringBuilder normalized = new StringBuilder();
679	        for (int i = 0; i < tokens.length; i++) {
680	            if (i > 0) {
681	                normalized.append(' ');
682	            }
683	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
684	        }
685	        return normalized.toString();
686	    }
687	}
